/* ============================ AD SLOTS ============================
   Google AdSense preparation — NO real ads are live yet.

   ADSENSE_PUBLISHER_ID is intentionally EMPTY. Do not paste an ID
   here until Ben has applied to Google AdSense himself, been
   approved, and is serving ViceSunshine from his own domain. While the
   ID is empty, every <AdSlot> renders only a small, clearly-labelled
   "Ad space" placeholder (a reserved space, never a fake ad) — and
   renders NOTHING for Premium members, because ad-free is a Premium
   benefit.

   When the ID is set later, each slot below maps 1:1 to an AdSense
   ad unit (same `slot` name) and the loader can be added in this one
   place. Ad policy for this site, permanently: NO crypto, gambling,
   or account-selling ads, ever — enforce it with AdSense category /
   advertiser blocking when the account is set up, and it is also
   stated in the Terms and the ads disclosure (About page).
   ================================================================ */
const ADSENSE_PUBLISHER_ID = "";

function AdSlot({
  slot,
  format = "banner",
  premium,
  flush = false,
}: {
  slot: string;
  format?: "banner" | "infeed" | "vertical" | "sidebar" | "thin";
  premium: boolean;
  flush?: boolean;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const live = ADSENSE_PUBLISHER_ID.trim().length > 0;
  useEffect(() => {
    if (!live || premium || !ref.current) return;
    const el = ref.current;
    if (el.dataset.loaded) return;
    el.dataset.loaded = "1";
    const s = document.createElement("script");
    s.async = true;
    s.crossOrigin = "anonymous";
    s.src = `https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${ADSENSE_PUBLISHER_ID}`;
    document.head.appendChild(s);
  }, [live, premium]);
  // Premium members never see ads — anywhere on the site.
  if (premium) return null;
  const heights: Record<string, number> = {
    banner: 48,
    infeed: 120,
    vertical: 420,
    sidebar: 132,
    thin: 36,
  };
  const h = heights[format] ?? 48;
  // Theme-matched placeholder (owner's direction: clean and
  // aesthetic, blending with the site while still clearly labelled
  // as an ad): dark navy panel, a soft hot-pink → neon-purple →
  // teal gradient hairline border (see .ad-slot in theme.css), a
  // small "AD" pill, and honest copy — never a fake advert.
  if (!live) {
    if (format === "thin") {
      // Sidebar strip (owner's direction): full width of the
      // sidebar, edge to edge, but really thin in height — a
      // banner line, not a box.
      return (
        <div
          ref={ref}
          role="complementary"
          aria-label={`Advertisement space (${slot})`}
          data-ad-slot={slot}
          className="ad-slot ad-slot-thin flex w-full items-center justify-center gap-2"
          style={{ minHeight: h }}
        >
          <span className="ad-pill">Ad</span>
          <span className="text-[11px] font-semibold text-[var(--dim)]">Ad space</span>
        </div>
      );
    }
    if (format === "banner") {
      // Page banner — including the bottom ad on the page
      // (owner's direction): wide and thin, stretched right
      // across the full width of the page, low height — a slim
      // horizontal strip in a single row, NOT a tall, chunky,
      // bulky box. The copy sits inline beside the pill instead
      // of stacked underneath it, so the strip stays shallow
      // even on a phone (it may wrap to two short lines there,
      // never a tall card).
      return (
        <div
          ref={ref}
          role="complementary"
          aria-label={`Advertisement space (${slot})`}
          data-ad-slot={slot}
          className={`ad-slot ad-slot-wide ${flush ? "" : "my-3"} flex w-full flex-wrap items-center justify-center gap-x-2.5 gap-y-0.5 px-4 py-2 text-center`}
          style={{ minHeight: h }}
        >
          <span className="ad-pill">Ad</span>
          <span className="text-[12px] font-bold text-[var(--text)]">Ad space</span>
          <span className="text-[11.5px] leading-snug text-[var(--dim)]">
            Reserved for ads when ViceSunshine is published — nothing is advertised here yet.
          </span>
        </div>
      );
    }
    return (
      <div
        ref={ref}
        role="complementary"
        aria-label={`Advertisement space (${slot})`}
        data-ad-slot={slot}
        className={`ad-slot ${flush ? "" : "my-4"} flex w-full flex-col items-center justify-center gap-1.5 px-4 text-center`}
        style={{ minHeight: h }}
      >
        <span className="ad-pill">Ad</span>
        <p className="text-[13px] font-bold text-[var(--text)]">Ad space</p>
        <p className="max-w-[420px] text-xs leading-relaxed text-[var(--dim)]">
          Reserved for ads when ViceSunshine is published — nothing is advertised here yet.
        </p>
      </div>
    );
  }
  return (
    <div ref={ref} className={flush ? undefined : format === "banner" ? "my-3" : "my-4"} style={{ minHeight: h }} aria-label={`Advertisement (${slot})`}>
      <ins
        className="adsbygoogle"
        style={{ display: "block", minHeight: h }}
        data-ad-client={ADSENSE_PUBLISHER_ID}
        data-ad-slot={slot}
        data-ad-format={format === "vertical" ? "fluid" : format === "banner" ? "horizontal" : "auto"}
        data-full-width-responsive="true"
      />
    </div>
  );
}

