// Settings → Connectors admin block: set the ViceSunshine Discord server
// invite link everyone sees on the one Discord card (Create Account page).
// Stored server-side (meta), validated as a real Discord invite URL
// by the action. No card preview here — the card lives in one place.
function DiscordInviteSettings() {
  const qc = useQueryClient();
  const invite = useQuery({ queryKey: ["discord-invite"], queryFn: () => api.getDiscordInvite({}) });
  const [url, setUrl] = useState("");
  const [hydrated, setHydrated] = useState(false);
  const [msg, setMsg] = useState("");
  useEffect(() => {
    if (!invite.data || hydrated) return;
    setUrl(invite.data.url);
    setHydrated(true);
  }, [invite.data, hydrated]);
  const save = useMutation({
    mutationFn: async () => await api.setDiscordInvite({ url: url.trim() }),
    onSuccess: (res) => {
      setMsg(res.url ? "Saved — the Join button is now live on the Discord card on the Create Account page." : "Invite link cleared — the Discord card on the Create Account page shows the coming-soon placeholder again.");
      qc.invalidateQueries({ queryKey: ["discord-invite"] });
    },
    onError: (e) => setMsg(e.message),
  });
  return (
    <div className="mt-5 rounded-2xl border border-[var(--border)] bg-[var(--surface2)] p-4">
      <h4 className="font-bold">ViceSunshine Discord server — admin</h4>
      <p className="mt-1 text-[13px] leading-relaxed text-[var(--dim)]">
        The one invite link for the whole community. It powers the single “Join our Discord server” card on the Create Account page — the card lives there only, nowhere else. Leave it empty to show “Discord invite coming soon — link will be added here”.
      </p>
      <label className="flabel" htmlFor="set-discord-invite">Discord invite link</label>
      <input id="set-discord-invite" className="field" {...FIELDS.setDiscordInvite.url} value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://discord.gg/your-invite" autoComplete="off" aria-label="ViceSunshine Discord server invite link" />
      <div className="mt-3 flex flex-wrap gap-2">
        <button type="button" className="btn-primary" style={{ minHeight: 44 }} disabled={save.isPending || !hydrated} onClick={() => { setMsg(""); save.mutate(); }} aria-label="Save the Discord invite link">
          {save.isPending ? "Saving…" : "Save invite link"}
        </button>
        {invite.data?.url ? (
          <a className="btn-ghost" style={{ minHeight: 44, padding: "8px 16px" }} href={invite.data.url} target="_blank" rel="noreferrer noopener" aria-label="Open the current Discord invite link — External link — Discord">Open current link</a>
        ) : null}
      </div>
      {msg && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]" role="status">{msg}</p>}
      <p className="mt-2 flex items-center gap-1.5 text-[12px] text-[var(--dim)]">
        <StatusLight tone={invite.data?.url ? "on" : "check"} size={8} />
        Current state: {invite.data?.url ? "Live — players can join from the Discord card on the Create Account page." : "Not set — coming-soon placeholder is showing."}
      </p>
    </div>
  );
}

