// Which sidebar dropdown a tab lives in. Navigation FOLLOWS the
// player (owner's direction): pressing a link anywhere — "View in
// Easter Eggs" while in Your Agent, a News link, a Database preset —
// closes the dropdown they were in and opens the dropdown the
// destination belongs to. Only one dropdown is ever open at a time
// (the accordion state in the shell), so opening the new one closes
// the old one by construction. Tabs that live in no dropdown
// (Premium, legal, sign-up, owner) return "" and leave the sidebar
// as it is.
type NavSectionId = "agent" | "explore" | "db" | "community";
function navSectionForTab(t: Tab): NavSectionId | "" {
  // "map" lives in Your Agent (owner's direction): the Map item sits
  // in the Your Agent dropdown, so pressing Map keeps Your Agent open
  // — it must NEVER switch the sidebar to Explore.
  if (t === "home" || t === "saved" || t === "ideas" || t === "goals" || t === "profile" || t === "analytics" || t === "map") return "agent";
  if (t === "database") return "db";
  if (t === "clans" || t === "challenges" || t === "customise" || t === "events" || t === "messages" || t === "discord") return "community";
  // "leaderboard" deliberately returns "" (Ben's direction): opening
  // the Leaderboard must NOT move the sidebar — it stays on whatever
  // section the player was in instead of jumping to Community.
  if (t === "feed" || t === "clips" || t === "news" || t === "bugs" || t === "eggs" || t === "guides") return "explore";
  // "updates" lives in no dropdown anymore (no sidebar entry): it
  // returns "" so the sidebar is left as it is when the full
  // Updates tab is opened from Home's Latest Update box.
  return "";
}

// Every tab, section and sub-page in ViceSunshine opens at the very TOP —
// never at the bottom or halfway down. Different webviews scroll
// different elements (the window, the document, or the shell's root
// container), so ALL of them are reset; and because a freshly opened
// view keeps growing while its data and images load — which can drag
// the scroll position back down — scrollPageToTopSoon re-asserts the
// top over the next few frames until the new view has settled.
function scrollPageToTop() {
  try { window.scrollTo({ top: 0, left: 0, behavior: "instant" as ScrollBehavior }); } catch { window.scrollTo(0, 0); }
  const scrollers: (Element | null)[] = [
    document.scrollingElement,
    document.documentElement,
    document.body,
    document.querySelector("[data-hatch-space-root]"),
    document.querySelector("[data-generated-space-root]"),
    document.querySelector("main"),
  ];
  for (const el of scrollers) {
    if (el && el.scrollTop !== 0) el.scrollTop = 0;
  }
}
let scrollTopTimers: number[] = [];
function scrollPageToTopSoon() {
  scrollPageToTop();
  for (const t of scrollTopTimers) window.clearTimeout(t);
  scrollTopTimers = [];
  requestAnimationFrame(() => scrollPageToTop());
  for (const ms of [80, 250, 600]) {
    scrollTopTimers.push(window.setTimeout(() => scrollPageToTop(), ms));
  }
}

// Back navigation (owner's direction): pressing a box / card to open
// a detail view remembers EXACTLY where the player was — page and
// scroll position — and that view's Back button returns them to the
// same page at the same spot, no refresh, no jump to the top. The
// shell's <main> is the element that scrolls, so the position is
// read from / written to it (with the window and document as
// fallbacks, mirroring scrollPageToTop). Restoring re-asserts the
// position over the next second while the returning view's data
// and images load and its height settles.
function currentScrollY(): number {
  const main = document.querySelector("main");
  if (main && main.scrollTop > 0) return main.scrollTop;
  return window.scrollY || document.documentElement?.scrollTop || 0;
}
let scrollYTimers: number[] = [];
function scrollPageToYSoon(y: number) {
  const apply = () => {
    try { window.scrollTo(0, y); } catch { /* older webview */ }
    const scrollers: (Element | null)[] = [
      document.scrollingElement,
      document.documentElement,
      document.body,
      document.querySelector("[data-hatch-space-root]"),
      document.querySelector("[data-generated-space-root]"),
      document.querySelector("main"),
    ];
    for (const el of scrollers) {
      if (el) el.scrollTop = y;
    }
  };
  apply();
  for (const t of scrollYTimers) window.clearTimeout(t);
  scrollYTimers = [];
  requestAnimationFrame(apply);
  for (const ms of [80, 250, 600, 1000]) {
    scrollYTimers.push(window.setTimeout(apply, ms));
  }
}


function SectionTitle({ children, sub }: { children: ReactNode; sub?: string }) {
  return (
    <div className="mb-4">
      <h2 className="text-[28px] font-extrabold leading-tight tracking-tight">{children}</h2>
      {sub ? <p className="mt-1 text-sm text-[var(--dim)]">{sub}</p> : null}
    </div>
  );
}

function EmptyNote({ children }: { children: ReactNode }) {
  return (
    <div className="card p-5 text-sm text-[var(--dim)]">{children}</div>
  );
}

type PlayerLinksData = {
  psn: string;
  xbox: string;
  discord: string;
  // Rockstar Social Club ID, already visibility-filtered by the
  // server: it only arrives here when the player made it public, or
  // the viewer is the player or their crew mate.
  rockstar: string;
  others: { label: string; url: string }[];
};

function CopyButton({ value, label }: { value: string; label: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost"
      style={{ minHeight: 32, padding: "4px 10px", fontSize: 12 }}
      aria-label={`Copy ${label}: ${value}`}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        } catch {
          setCopied(false);
        }
      }}
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

function PlayerLinks({ links, name }: { links: PlayerLinksData; name: string }) {
  const rows: { icon: string; label: string; value: string; href?: string; rockstar?: boolean }[] = [];
  // Rockstar first — it is the fastest way to add a player in-game:
  // one tap copies the Social Club ID, ready to paste into Social
  // Club's friend search.
  if (links.rockstar) rows.push({ icon: "RS", label: "Rockstar", value: links.rockstar, rockstar: true });
  if (links.psn) rows.push({ icon: "PS", label: "PlayStation / PSN", value: links.psn });
  if (links.xbox) rows.push({ icon: "XB", label: "Xbox", value: links.xbox });
  if (links.discord) rows.push({ icon: "DC", label: "Discord", value: links.discord });
  for (const o of links.others) {
    rows.push({
      icon: "Link",
      label: o.label,
      value: o.url,
      href: /^https?:\/\//i.test(o.url) ? o.url : undefined,
    });
  }
  if (rows.length === 0) return null;
  return (
    <div className="mt-2 flex flex-wrap gap-1.5" aria-label={`${name}'s linked accounts`}>
      {rows.map((r) => (
        <span
          key={`${r.label}-${r.value}`}
          className="inline-flex items-center gap-1.5 rounded-full bg-[var(--surface2)] py-1 pl-2.5 pr-1 text-xs font-semibold"
        >
          <span aria-hidden="true">{r.icon}</span>
          {r.href ? (
            <a href={r.href} target="_blank" rel="noreferrer" className="underline" aria-label={`Open ${name}'s ${r.label} link`}>
              {r.label}: {r.value.replace(/^https?:\/\//, "").slice(0, 34)}
            </a>
          ) : (
            <span>{r.label}: {r.value}</span>
          )}
          <CopyButton value={r.value} label={`${r.label} for ${name}`} />
          {r.rockstar && <AddOnRockstarButton value={r.value} name={name} />}
        </span>
      ))}
    </div>
  );
}

/* The quick "Add on Rockstar" action: one tap copies the player's
   Social Club ID and says exactly what to do with it — paste it into
   Social Club's friend search. There is no Rockstar API a fan site
   can call, so copying the ID IS the fastest real add flow. */
function AddOnRockstarButton({ value, name }: { value: string; name: string }) {
  const [added, setAdded] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost"
      style={{ minHeight: 32, padding: "4px 10px", fontSize: 12, borderColor: "rgba(255,46,136,0.5)", color: "var(--accent)" }}
      aria-label={`Add ${name} on Rockstar — copies their Social Club ID`}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setAdded(true);
          setTimeout(() => setAdded(false), 2600);
        } catch {
          setAdded(false);
        }
      }}
    >
      {added ? "Copied — paste it in Social Club" : "Add on Rockstar"}
    </button>
  );
}

function StatusBadge({ status }: { status: string }) {
  const color = status.startsWith("Fixed")
    ? "var(--accent2)"
    : status === "Confirmed"
      ? "var(--accent2)"
      : status === "Rumor"
        ? "var(--amber)"
        : status === "Investigating"
          ? "#4FC3F7"
          : "var(--dim)";
  return (
    <span
      className="inline-block rounded-full px-2.5 py-0.5 text-xs font-bold"
      style={{ border: `1px solid ${color}`, color }}
    >
      {status}
    </span>
  );
}

function CategoryBadge({ category }: { category: string }) {
  const map: Record<string, string> = {
    Official: "var(--accent2)",
    Patch: "#4FC3F7",
    Rumor: "var(--amber)",
    Community: "var(--accent)",
  };
  const c = map[category] ?? "var(--dim)";
  return (
    <span
      className="inline-block rounded-full px-2.5 py-0.5 text-xs font-bold uppercase tracking-wide"
      style={{ border: `1px solid ${c}`, color: c }}
    >
      {category}
      {category === "Rumor" ? " — unconfirmed" : ""}
    </span>
  );
}

