const MAP_PIN_GROUPS = ["Services", "Food and Drink", "Activities", "Racing and Stunts", "Travel", "Collectibles", "Places"];
/* Categories hidden on first open — the same set the owner's
   reference link hides, so the map opens at "316 of 1020 pins
   shown" and every other category is one tap on Show away. */
const MAP_DEFAULT_HIDDEN = ["fast-food", "liquor-stores", "golf", "stunt-jumps", "base-jumps", "knife-flights", "under-the-bridge", "standout-vehicles", "randy-vehicles", "moses-vehicles", "ferry-terminals", "trains", "collectible-cards", "safes", "curiosities"];
const MAP_CAT_BY_ID: Record<string, MapPinCatDef> = Object.fromEntries(MAP_PIN_CATS.map((c) => [c.id, c]));
/* ---- The base map itself: YANIS V18 by Yanis and the GTA VI
   Mapping Community, via GTADB (GTA VI Map Tiles, CC BY 4.0) —
   a real tile pyramid, not a flat picture: 512px WebP tiles over
   zoom levels 0-8, loaded from GTAMap.io's public tile CDN, which
   builds its tiles from the GTADB community map (GTADB's own tile
   host refuses hotlinking, so the community's public CDN is what
   fan sites load). Native world: a 131,072px square; the YANIS
   art sits in IMG_RECT; our view crop frames it with a sea
   margin. Credit lives in the panel footer and under the map. ---- */
const TILE_BASE = "https://tiles.gtamap.io/gta6/community-v18-4x";
const TILE_PX = 512;
const WORLD_NATIVE = 131072;
const IMG_RECT = { x0: 21504, y0: 21504, x1: 80896, y1: 102400 };
const CROP = { x0: 14400, y0: 16000, x1: 84800, y1: 109600 };
const CROP_W = CROP.x1 - CROP.x0;
const CROP_H = CROP.y1 - CROP.y0;
const CROP_CX = (CROP.x0 + CROP.x1) / 2;
const CROP_CY = (CROP.y0 + CROP.y1) / 2;
const SEA_DAY = "#2c68a6";
/* Night sea = the day sea run through the tile layer's own night
   filter (brightness .55 / saturate .85 / contrast 1.06), so the
   surround outside the tile rectangle matches the filtered tiles
   almost exactly — no visible rectangle edge at full zoom-out. */
const SEA_NIGHT = "#163356";
/* Map surface colours, matched to the reference map's palette:
   the sea is the YANIS tiles' own sampled sea blue (#2c68a6 —
   the exact dominant pixel of the tile pyramid, so the stage
   blends seamlessly into the tiles at every edge), and every
   floating surface on the map — the left panel, the pin detail
   card, the zoom / Day-Night control stack, the notice pill and
   the panel reopen button — shares ONE flat dark panel colour
   with the same border, like the reference: no gradients, no
   per-surface tints. */
const MAP_PANEL_BG = "rgba(21,23,32,0.97)";
const MAP_CTRL_BG = "rgba(17,19,27,0.95)";
const MAP_PANEL_BORDER = "rgba(255,255,255,0.09)";
/* Coastline of the YANIS V18 landmass in our map-% space, traced
   from the community map so ViceSunshine's own schematic pins
   land on its real geography: Vice City on the south-east coast,
   Port Gellhorn on the west coast, Ambrosia in the centre,
   Mount Kalaga in the north and the Keys trailing south-west.
   The pins themselves are still ViceSunshine's schematic
   placements — every location stays unverified. */
const LAND_UV: [number, number][] = [
  [26.1, 9.3], [33.1, 7.0], [42.4, 5.9], [51.7, 6.4], [61.0, 5.9], [68.0, 8.7], [72.6, 13.3], [76.7, 19.0],
  [78.5, 25.8], [79.0, 32.6], [87.8, 37.2], [90.7, 44.0], [90.1, 52.0], [84.3, 55.9], [75.0, 57.1],
  [68.0, 59.9], [61.0, 65.0], [55.2, 67.3], [45.9, 66.8], [37.7, 65.0], [29.6, 61.6], [22.0, 54.8],
  [18.5, 48.5], [20.9, 43.4], [16.2, 39.4], [14.5, 34.3], [18.5, 29.8], [16.2, 24.7], [13.3, 19.5],
  [17.4, 15.0], [21.4, 11.6],
];
/* [cx, cy, rx, ry] for the offshore islands: the Vice Beach
   barrier island, the north-east barrier chain, the west-coast
   islets, Port Gellhorn's island and the Leonida Keys chain. */
const ISLAND_UV: [number, number, number, number][] = [
  [89.8, 44.5, 2.2, 8], [77.5, 26, 1.6, 7], [15.5, 22, 4, 6], [20.3, 28.6, 3.4, 3],
  [24, 75, 6, 2.2], [33, 74.5, 7, 2.2], [43, 73.5, 7, 2.4], [53, 70.5, 6, 2.6], [60, 68, 4, 2.4], [17.4, 73.6, 3, 2.4],
];
function mapPointInPoly(x: number, y: number, poly: [number, number][]): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i] ?? [0, 0];
    const b = poly[j] ?? [0, 0];
    if ((a[1] > y) !== (b[1] > y) && x < ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]) + a[0]) inside = !inside;
  }
  return inside;
}
/* Is a map-% point on land on the YANIS V18 base? Mainland
   polygon or an island — and never in Lake Leonida. Pins are
   re-sampled until they land, so no pin ever floats in the sea. */
function mapOnLand(x: number, y: number): boolean {
  const lx = (x - 62.7) / 5.8; const ly = (y - 24.7) / 4.0;
  if (lx * lx + ly * ly < 1) return false;
  if (mapPointInPoly(x, y, LAND_UV)) return true;
  for (const [cx, cy, rx, ry] of ISLAND_UV) {
    const dx = (x - cx) / rx; const dy = (y - cy) / ry;
    if (dx * dx + dy * dy < 1) return true;
  }
  return false;
}
const MAP_ZONES = [
  { cx: 71, cy: 41, rx: 11, ry: 10, w: 52 },
  { cx: 47, cy: 50, rx: 10, ry: 9, w: 14 },
  { cx: 44, cy: 61, rx: 10, ry: 6, w: 10 },
  { cx: 26, cy: 36, rx: 8, ry: 13, w: 12 },
  { cx: 40, cy: 73, rx: 16, ry: 3.5, w: 6 },
  { cx: 50, cy: 21, rx: 11, ry: 7, w: 6 },
];
function mapRand(seed: number) { let t = seed + 0x6d2b79f5; return () => { t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const MAP_SCHEMATIC_PINS: { catId: string; x: number; y: number }[] = (() => {
  const out: { catId: string; x: number; y: number }[] = [];
  MAP_PIN_CATS.forEach((cat, ci) => {
    const rnd = mapRand(1234 + ci * 977);
    for (let i = 0; i < cat.count; i++) {
      let pick = rnd() * 100; let zone = MAP_ZONES[0]!;
      for (const z of MAP_ZONES) { if (pick < z.w) { zone = z; break; } pick -= z.w; }
      let px = zone.cx; let py = zone.cy;
      let placed = false;
      for (let attempt = 0; attempt < 14 && !placed; attempt++) {
        const gx = ((rnd() + rnd() + rnd()) / 3) * 2 - 1;
        const gy = ((rnd() + rnd() + rnd()) / 3) * 2 - 1;
        const candX = Math.min(97, Math.max(3, zone.cx + gx * zone.rx));
        const candY = Math.min(97, Math.max(3, zone.cy + gy * zone.ry));
        if (mapOnLand(candX, candY)) { px = candX; py = candY; placed = true; }
      }
      if (!placed) {
        // Fall back to the nearest on-land anchor around the zone
        // centre (expanding grid search) — a pin never keeps an
        // off-land candidate, so no pin floats in the sea or lake.
        let found = false;
        for (let r = 0; r <= 12 && !found; r += 1.5) {
          for (let a = 0; a < Math.PI * 2 && !found; a += Math.PI / 6) {
            const ax = zone.cx + Math.cos(a) * r;
            const ay = zone.cy + Math.sin(a) * r;
            if (mapOnLand(ax, ay)) { px = ax; py = ay; found = true; }
          }
        }
      }
      out.push({ catId: cat.id, x: px, y: py });
    }
  });
  return out;
})();
